USE parksmart;
INSERT INTO Rol (nombreRol,descripcion,estado) SELECT 'PROVEEDOR','Proveedor que publica sectores y espacios de parqueo.','ACTIVO' WHERE NOT EXISTS(SELECT 1 FROM Rol WHERE nombreRol='PROVEEDOR');
CREATE TABLE IF NOT EXISTS Proveedor(idProveedor BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,idUsuario BIGINT UNSIGNED NULL,nombreComercial VARCHAR(120) NOT NULL,identificacionFiscal VARCHAR(30) NULL,telefono VARCHAR(20) NOT NULL,correoElectronico VARCHAR(120) NOT NULL,direccion VARCHAR(250) NULL,estado ENUM('PENDIENTE','ACTIVO','INACTIVO','SUSPENDIDO') NOT NULL DEFAULT 'PENDIENTE',fechaCreacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fechaActualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(idProveedor),UNIQUE KEY uk_proveedor_usuario(idUsuario),UNIQUE KEY uk_proveedor_fiscal(identificacionFiscal),CONSTRAINT fk_proveedor_usuario FOREIGN KEY(idUsuario) REFERENCES Usuario(idUsuario) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE Usuario ADD COLUMN idProveedor BIGINT UNSIGNED NULL;
ALTER TABLE Usuario ADD UNIQUE KEY uk_usuario_proveedor(idProveedor);
ALTER TABLE Usuario ADD CONSTRAINT fk_usuario_proveedor FOREIGN KEY(idProveedor) REFERENCES Proveedor(idProveedor) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE Sector ADD COLUMN idProveedor BIGINT UNSIGNED NULL;
ALTER TABLE Sector ADD COLUMN latitud DECIMAL(10,7) NULL;
ALTER TABLE Sector ADD COLUMN longitud DECIMAL(10,7) NULL;
ALTER TABLE Sector ADD COLUMN precioHora DECIMAL(10,2) NOT NULL DEFAULT 0;
ALTER TABLE Sector ADD CONSTRAINT fk_sector_proveedor FOREIGN KEY(idProveedor) REFERENCES Proveedor(idProveedor) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE Espacio ADD COLUMN latitud DECIMAL(10,7) NULL;
ALTER TABLE Espacio ADD COLUMN longitud DECIMAL(10,7) NULL;
CREATE TABLE IF NOT EXISTS consentimiento_privacidad(idConsentimiento BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,idUsuario BIGINT UNSIGNED NOT NULL,versionAviso VARCHAR(20) NOT NULL,finalidad VARCHAR(500) NOT NULL,aceptado TINYINT(1) NOT NULL DEFAULT 1,fechaAceptacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(idConsentimiento),KEY ix_consentimiento_usuario(idUsuario),CONSTRAINT fk_consentimiento_usuario FOREIGN KEY(idUsuario) REFERENCES Usuario(idUsuario) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
